css:
.neo-checkbox {
  --border-thick: 3px;
  --shadow-offset: 4px;
  --shadow-color: #000000;
  --bg-unchecked: #ffe600;
  --bg-checked: #ff3366;
  --check-color: #000000;
  --text-color: #000000;

  --accept-shadow-color: #ff007f;
  --terms-shadow-color: #00f0ff;
  --shadow-distance: 3px;

  --focus-ring: #00f0ff;
  --font-family: "Arial Black", "Impact", sans-serif;

  display: inline-flex;
  align-items: center;
  gap: 1em;
  cursor: pointer;
  font-family: var(--font-family);
  font-size: 1.2rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-color);
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  padding: 0.6em;
}

.neo-checkbox__input {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.neo-checkbox__box {
  position: relative;
  width: 2.1em;
  height: 2.1em;
  flex-shrink: 0;
  background: var(--bg-unchecked);
  border: var(--border-thick) solid var(--shadow-color);
  box-shadow: var(--shadow-offset) var(--shadow-offset) 0 0 var(--shadow-color);
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    transform 0.15s cubic-bezier(0.175, 0.885, 0.32, 1.275),
    box-shadow 0.15s ease,
    background 0.2s ease;
}

.neo-checkbox__icon {
  font-size: 1.4em;
  font-weight: 900;
  color: var(--check-color);
  transform: scale(0) rotate(-45deg);
  opacity: 0;
  transition:
    transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1),
    opacity 0.15s ease;
}

.neo-checkbox__label {
  display: inline-flex;
  gap: 0.5em;
  position: relative;
}

.word-accept,
.word-terms {
  color: #000000;
  text-shadow: 0 0 0 transparent;
  transition:
    transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1),
    text-shadow 0.2s ease;
}

.neo-checkbox:hover .neo-checkbox__box {
  transform: translate(-3px, -3px);
  box-shadow: calc(var(--shadow-offset) + 3px) calc(var(--shadow-offset) + 3px)
    0 0 var(--shadow-color);
}

.neo-checkbox:hover .word-accept {
  transform: translateY(-3px);
  text-shadow: var(--shadow-distance) var(--shadow-distance) 0
    var(--accept-shadow-color);
}

.neo-checkbox:hover .word-terms {
  transform: translateY(3px);
  text-shadow: var(--shadow-distance) var(--shadow-distance) 0
    var(--terms-shadow-color);
}

.neo-checkbox__input:checked + .neo-checkbox__box {
  background: var(--bg-checked);
  animation: boxPop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.neo-checkbox__input:checked + .neo-checkbox__box .neo-checkbox__icon {
  transform: scale(1) rotate(0deg);
  opacity: 1;
}

.neo-checkbox:active .neo-checkbox__box {
  transform: translate(var(--shadow-offset), var(--shadow-offset));
  box-shadow: 0 0 0 0 var(--shadow-color);
}

.neo-checkbox:active {
  transform: scale(0.98);
}

@keyframes boxPop {
  0% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.15) rotate(5deg);
  }
  100% {
    transform: scale(1);
  }
}

.neo-checkbox__input:focus-visible + .neo-checkbox__box {
  outline: 3px solid var(--focus-ring);
  outline-offset: 4px;
}
